constexpr auto kEmojiList = makeEmojiList();

constexpr int emojiPopupRowWidth(const EmojiEntry& entry)
{
    return emojiGlyphWidth(entry.emoji) + 1 + emojiCStringLen(entry.name);
}

constexpr int makeEmojiPopupMaxWidth()
{
    int maxWidth = 12;
    for(const auto& entry : kEmojiList)
    {
        int rowWidth = emojiPopupRowWidth(entry);
        if(rowWidth > maxWidth)
            maxWidth = rowWidth;
    }
    return maxWidth;
}

constexpr int kEmojiPopupMaxWidth = makeEmojiPopupMaxWidth();
